using System;using System.IO;using ReFix.Shared;
namespace ReFix.Tests{static class MiniIconsModelTests{
 internal static void Run(Action<string,bool> report){string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"mini-model-"+Guid.NewGuid().ToString("N"));try{var store=new MiniIconsStore(root);var p=store.Load();report("mini-icons initially transfers only known first-party apps",p.OwnTransfers.Count==4&&p.OwnTransfers.Contains("hub")&&!p.ShowWindowsTray);p.OwnTransfers.Remove("quiet-mixer");p.OwnOrder.Reverse();p.IconSize=28;p.Columns=3;p.ShowWindowsTray=true;store.Save(p);var loaded=store.Load();report("mini-icons transfer grouping order size and external choice persist",!loaded.OwnTransfers.Contains("quiet-mixer")&&loaded.OwnOrder[0]=="quick-note"&&loaded.IconSize==28&&loaded.Columns==3&&loaded.ShowWindowsTray);var clone=p.Clone();clone.OwnTransfers.Clear();report("mini-icons snapshots own lists",p.OwnTransfers.Count==3);p.OwnTransfers.Add("../escape");p.OwnTransfers.Add("hub");p.IconSize=200;p.Columns=-1;p.Normalize();report("mini-icons rejects malformed IDs duplicates and excess geometry",p.OwnTransfers.Count==3&&p.IconSize==32&&p.Columns==1);File.WriteAllText(store.FilePath,"{bad");report("mini-icons malformed settings retain safe defaults",store.Load().OwnTransfers.Count==4);var c=new ControlsProfile();c.AutoHideMiniIcons=false;c.StartMiniIconsWithHub=true;using(var controls=new ControlsStore(root)){controls.Save(c);controls.ResetDefaults();report("mini-icons behavior survives keyboard reset",!controls.Current.AutoHideMiniIcons&&controls.Current.StartMiniIconsWithHub);}report("mini-icons has distinct global and local keyboard actions",c.Get("mini-icons.toggle")=="Ctrl+Alt+I"&&c.Get("mini-icons.hide")=="Esc");}finally{if(Directory.Exists(root))Directory.Delete(root,true);}}
}}
